// ---------------------------------------------------------------------------
function classify(s) {
  for (const r of RULES) {
    if (r.f && !s.file.includes(r.f)) continue;
    if (r.p && !r.p.test(s.path || "")) continue;
    if (r.t) {
      const ok = typeof r.t === "function" ? r.t(s.text) : r.t.test(s.text);
      if (!ok) continue;
    }
    return r;
  }
  return null;
}

// ---------------------------------------------------------------------------
// `r: "@face"` — THE PART THAT MAKES RESTATED MEAN SOMETHING.
// A rule cannot say "this prose restates its own file"; that resolves to
// nothing and is the exact shape "436 records, kept since January 2024" would
// have taken. So a RESTATED row is resolved to THE SOURCED ROWS STANDING ON
// THE SAME FACE — the tombstone, the plate captions, the register lines that
// carry a citation. If a face has no sourced row on it, its prose is resting on
// nothing and the row falls to INVENTION. That is not a formality: it is the
// check that would have caught the Record's header furniture, which sat on a
// face whose only other content was more of itself.
function containerOf(ip) {
  const m = ip.match(/^(.*?(?:\.face|\.card))(\b|\.)/);
  if (m) return m[1];
  const m2 = ip.match(/^([^.]*\[\d+\])/);
  return m2 ? m2[1] : ip;
}

const s = sweep();
const entries = {};
const inventions = [];
const byClass = {};
const pass1 = [];

for (const str of s.strings) {
  const rule = classify(str);
  pass1.push({ str, rule, key: keyOf(str.file, str.text), container: str.file + "|" + containerOf(str.ipath || "") });
}

// Which faces carry a sourced row, and which keys they are.
const sourcedByContainer = new Map();
for (const p of pass1) {
  if (!p.rule || (p.rule.c !== "VERIFIED" && p.rule.c !== "MIKE")) continue;
  if (!sourcedByContainer.has(p.container)) sourcedByContainer.set(p.container, []);
  sourcedByContainer.get(p.container).push(p.key);
}

let restatedOrphans = 0;
for (const p of pass1) {
  const { str, rule } = p;
  const row = { f: str.file, l: str.line, t: str.text.length > 400 ? str.text.slice(0, 400) + "…" : str.text };
  if (str.path) row.p = str.path;

  if (!rule) {
    row.c = "INVENTION";
    row.n = "no rule matched in the 2026-08-04 backfill — no origin traced";
  } else {
    row.c = rule.c;
    if (rule.s) row.s = rule.s;
    if (rule.n) row.n = rule.n;
    if (rule.rText) {
      // Point at ONE named row by its exact text — the strongest reference
      // available, because it survives as a key and the gate re-checks it.
      const target = pass1.find((q) => q.str.file === str.file && q.str.text.trim() === rule.rText);
      if (target) row.r = [target.key];
      else { row.c = "INVENTION"; row.n = "declared as restating " + JSON.stringify(rule.rText) + ", which is not in the source"; }
    } else if (rule.r === "@face") {
      const sibs = (sourcedByContainer.get(p.container) || []).filter((k) => k !== p.key).slice(0, 6);
      if (sibs.length) {
        row.r = sibs;
      } else {
        row.c = "INVENTION";
        row.n = "RESTATED WITH NOTHING TO REST ON — this prose sits on a face ("
          + containerOf(str.ipath || "") + ") that carries no MIKE- or VERIFIED-class row for it to restate.";
        restatedOrphans++;
      }
    } else if (rule.r) {
      row.r = rule.r;
    }
  }
  if (row.c === "INVENTION") inventions.push({ ...str, note: row.n || "" });
  byClass[row.c] = (byClass[row.c] || 0) + 1;
  entries[p.key] = row;
}

const register = {
  _: "PROVENANCE REGISTER. Every visitor-facing string in the authored source, "
    + "with where it came from. Written by provenance/backfill-20260804.mjs; "
    + "maintained one row at a time thereafter. Read provenance/README.md first — "
    + "in particular what this cannot see.",
  inventionCeiling: inventions.length,
  generated: {
    "src/data/exhibits/hunter_root.json": {
      c: "VERIFIED",
      s: "MediaVault, the museum's own catalogue. Written by tools/export-artifacts.mjs from MV's released set; every artifact carries MV provenance.",
      n: "BULK-DECLARED AT FILE LEVEL, on purpose: re-hashing ~1,900 rows on every export would produce a diff nobody reads, and the claim being made is about the PIPELINE. Review the pipeline, not the rows.",
    },
    "src/data/exhibits/hunter_root.facts.json": {
      c: "VERIFIED",
      s: "MediaVault fact vault — 97 gated, sourced facts, exported by tools/export-artifacts.mjs",
      n: "Bulk-declared at file level. Same reasoning as hunter_root.json.",
    },
    "src/data/vocabulary.json": { c: "HOUSE", s: "generated tag vocabulary — filter/search slugs, not sentences" },
    "src/data/era-buckets.json": { c: "DERIVED", s: "derived era buckets, tools/era-derivation.mjs" },
  },
  entries,
};

if (process.argv.includes("--write")) {
  fs.mkdirSync(path.join(REPO, "provenance"), { recursive: true });
  fs.writeFileSync(path.join(REPO, "provenance", "register.json"), JSON.stringify(register, null, 1) + "\n");
  console.log("wrote provenance/register.json");
}

console.log("\nCLASSIFIED " + s.strings.length + " strings:");
for (const [c, n] of Object.entries(byClass).sort((a, b) => b[1] - a[1]))
  console.log("  " + c.padEnd(10) + String(n).padStart(5));
console.log("\nINVENTION (" + inventions.length + "):");
for (const i of inventions) console.log("  " + i.file + ":" + i.line + "  " + JSON.stringify(i.text.slice(0, 120)));
console.log("\nRESTATED rows that had nothing to rest on: " + restatedOrphans);
